import{t as e}from"./buildPage-DWQZYYcs.js";var t=e({slug:`esthetician-audit`,heroTitle:`Audit your esthetics business in minutes`,heroSubtitle:`Perplexity Computer reviews your esthetics site, services, booking flow, reviews, and local visibility, then ranks the fixes most likely to drive appointments.`,inputUrlCta:`Audit my business`,inputUrlPlaceholder:`yourstudio.com`,inputUrlPrefill:`Go to {url} and run a full esthetics business audit. 1) Review the website for service clarity, treatment menu structure, before-and-after proof, booking flow, and mobile conversion issues. 2) Audit local visibility, reviews, Google Business Profile signals, and social proof. 3) Benchmark nearby estheticians or med spas where useful. 4) Recommend the highest-impact changes for appointment bookings and local discovery. 5) Deliver a prioritized action plan with rewritten copy, offer ideas, and next steps.`,heroOverlaySteps:[`Reviewing services, treatment menu, proof, and booking flow`,`Analyzing local visibility, reviews, and social proof`,`Benchmarking nearby estheticians and med spas`,`Prioritized booking-growth audit with copy fixes ready to use`],generatingSteps:[`Visiting {url} to review your esthetics site and booking journey`,`Designing an agent to benchmark nearby providers and visibility signals`,`Configuring recommendations for service clarity, proof, and conversion fixes`,`Packaging the work into a prioritized appointment-growth action plan`],featureSectionTitle:`From local visibility gaps to more booked treatments`,featureCardTitles:[`Connects to your booking workflow`,`Fixes you can launch now`],featureCardDescriptions:[`Computer separates your audit into site review, treatment positioning, local visibility, and competitor benchmarking so the plan reflects how clients choose a provider.`,`Google Business Profile, booking tools, Docs, Sheets, and planning notes can stay connected so marketing fixes move into execution.`,`Service-page rewrites. Offer ideas. Local SEO priorities. Booking-flow improvements. Computer gives you updates tied to more appointments.`],capabilitySectionTitle:`Your esthetics growth analyst, on demand`,capabilitySectionSubtitle:`Paste your business URL, step away, and come back to a clearer plan to drive appointments.`,capabilityCards:[{title:`Website Audit`,description:`Computer can review treatment pages, pricing clarity, before-and-after proof, booking flow, and mobile UX to find conversion gaps.`},{title:`Local Visibility Review`,description:`Computer can assess reviews, listings, Google Business Profile signals, and local search cues to show where nearby providers are winning.`},{title:`Offer Positioning`,description:`Computer can rewrite service messaging, package descriptions, and call-to-action language so prospects know why to book.`},{title:`Connect Your Tools`,description:`Computer can organize recommendations across booking tools, Google Business Profile, docs, and sheets so execution is easier.`},{title:`Remember Your Services`,description:`Computer can remember your treatments, client profile, pricing structure, and brand tone so future audits start from the right context.`},{title:`Refresh the Audit`,description:`Computer can revisit your presence later, compare changes, and suggest the next fix most likely to improve bookings.`}]});export{t as default};
